const staticData = $getWorkflowStaticData('global');
const offset = staticData.offset || 0;
return [{ json: { offset } }];

const staticData = $getWorkflowStaticData('global');
const data = $input.first().json;

if (!data.ok || !data.result || data.result.length === 0) {
  return [];
}

const updates = data.result;
const lastId = updates[updates.length - 1].update_id;
staticData.offset = lastId + 1;

const last = updates[updates.length - 1];
if (!last.message || !last.message.text) return [];

const cmd = last.message.text.trim().toLowerCase().split(' ')[0];
let route = 'help';
if (cmd === '/stats') route = 'stats';
else if (cmd === '/types') route = 'types';
else if (cmd === '/incomplete') route = 'incomplete';

return [{ json: { chatId: last.message.chat.id, route } }];

const route = $input.first().json.route;
const chatId = $input.first().json.chatId;
if (route === 'stats') return [{ json: { chatId, route } }];
return [];

const route = $input.first().json.route;
const chatId = $input.first().json.chatId;
if (route === 'types') return [{ json: { chatId, route } }];
return [];

const route = $input.first().json.route;
const chatId = $input.first().json.chatId;
if (route === 'incomplete') return [{ json: { chatId, route } }];
return [];

const route = $input.first().json.route;
const chatId = $input.first().json.chatId;
if (route === 'help') return [{ json: { chatId, route } }];
return [];

const d = $input.first().json;
const chatId = $('Parse Updates').first().json.chatId;
const total = d.total_pokemon;
const completes = d.fiches_completes;
const pct = total > 0 ? Math.round(completes * 100 / total) : 0;
const pctArt = total > 0 ? Math.round(d.with_artwork * 100 / total) : 0;
const pctSprite = total > 0 ? Math.round(d.with_sprite * 100 / total) : 0;
const storageMb = (d.total_storage_bytes / 1024 / 1024).toFixed(1);

const msg = '📊 KPI du Référentiel Pokémon\n\n' +
  '🔢 Total Pokémon : ' + total + '\n' +
  '✅ Fiches complètes : ' + completes + ' (' + pct + '%)\n' +
  '🖼 Avec artwork : ' + d.with_artwork + ' (' + pctArt + '%)\n' +
  '👾 Avec sprite : ' + d.with_sprite + ' (' + pctSprite + '%)\n' +
  '📁 Pokémon avec fichier brut : ' + d.pokemon_with_files + '\n' +
  '💾 Fichiers stockés (MinIO) : ' + d.total_files_stored + '\n' +
  '📦 Stockage total : ' + storageMb + ' Mo';

return [{ json: { chatId, text: msg } }];

const items = $input.all();
const chatId = $('Parse Updates').first().json.chatId;
const emojis = { water:'💧', fire:'🔥', grass:'🌿', electric:'⚡', poison:'☠️', normal:'⚪', ground:'🟤', fairy:'🧚', bug:'🐛', fighting:'🥊', psychic:'🔮', rock:'🪨', ghost:'👻', ice:'❄️', dragon:'🐉', dark:'🌑', steel:'⚙️', flying:'🕊️' };

let msg = '📋 Répartition par Type Principal\n\n';
for (const item of items) {
  const t = item.json;
  const emoji = emojis[t.main_type] || '▪️';
  msg += emoji + ' ' + t.main_type + ' : ' + t.nb_pokemon + ' (' + t.pct + '%)\n';
}

return [{ json: { chatId, text: msg } }];

const items = $input.all();
const chatId = $('Parse Updates').first().json.chatId;

if (items.length === 0 || !items[0].json.pokemon_id) {
  return [{ json: { chatId, text: '✅ Aucun Pokémon incomplet !\n\nToutes les fiches du référentiel sont complètes.' } }];
}

let msg = '⚠️ Pokémon Incomplets (' + items.length + ' affichés)\n\n';
for (const item of items) {
  const p = item.json;
  msg += '• #' + p.pokemon_id + ' ' + p.pokemon_name + ' — manque : ' + p.champs_manquants.trim() + '\n';
}

return [{ json: { chatId, text: msg } }];
